<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$u=mysqli_query($koneksi,"SELECT id_universitas,nama_universitas FROM universitas ORDER BY nama_universitas");$error='';$d=['kode_fakultas'=>'','nama_fakultas'=>'','id_universitas'=>1];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$d['kode_fakultas']=strtoupper(trim($_POST['kode_fakultas']??''));$d['nama_fakultas']=trim($_POST['nama_fakultas']??'');$d['id_universitas']=(int)($_POST['id_universitas']??1);if(!$d['kode_fakultas']||!$d['nama_fakultas'])$error='Kode dan nama fakultas wajib diisi.';if(!$error){$st=mysqli_prepare($koneksi,"INSERT INTO fakultas(id_universitas,kode_fakultas,nama_fakultas) VALUES(?,?,?)");mysqli_stmt_bind_param($st,'iss',$d['id_universitas'],$d['kode_fakultas'],$d['nama_fakultas']);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'fakultas',(string)mysqli_insert_id($koneksi),'INSERT',null,$d);flash('success','Fakultas berhasil ditambahkan.');redirect_to('fakultas.php');}$error='Gagal menyimpan data.';mysqli_stmt_close($st);}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Fakultas</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">MASTER DATA</span><h1>Tambah Fakultas</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>Kode Fakultas</label><input name="kode_fakultas" required value="<?=e($d['kode_fakultas'])?>"></div><div class="form-group"><label>Nama Fakultas</label><input name="nama_fakultas" required value="<?=e($d['nama_fakultas'])?>"></div><div class="form-group"><label>Universitas</label><select name="id_universitas"><?php while($x=mysqli_fetch_assoc($u)):?><option value="<?=$x['id_universitas']?>" <?=$d['id_universitas']==$x['id_universitas']?'selected':''?>><?=e($x['nama_universitas'])?></option><?php endwhile;?></select></div></div><div class="form-actions"><a class="btn btn-outline" href="fakultas.php">Batal</a><button class="btn btn-primary">Simpan</button></div><?=csrf_field()?></form></div></main><script src="script.js"></script></body></html>